<?php
require __DIR__ . '/auth.php'; require_login(); require __DIR__ . '/conexion.php';
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT); if(!$id){http_response_code(400);exit('Factura inválida');}
$s=$mysqli->prepare('SELECT * FROM ventas WHERE id=?');$s->bind_param('i',$id);$s->execute();$venta=$s->get_result()->fetch_assoc();$s->close();if(!$venta){http_response_code(404);exit('Factura no encontrada');}
$s=$mysqli->prepare('SELECT nombre_producto,precio,cantidad,subtotal FROM detalle_venta WHERE venta_id=?');$s->bind_param('i',$id);$s->execute();$items=$s->get_result();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Factura <?=htmlspecialchars($venta['numero'])?></title><style>body{font:15px Arial;background:#f2f7f5;margin:0;color:#243b37}.ticket{max-width:850px;margin:24px auto;background:white;padding:28px;border-radius:12px}h1{color:#087f73}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}.btn{background:#087f73;color:white;padding:10px 13px;border:0;border-radius:7px;text-decoration:none;cursor:pointer}.right{text-align:right}@media print{body{background:white}.noprint{display:none}.ticket{margin:0;box-shadow:none}}</style></head><body><main class="ticket"><div class="noprint"><button class="btn" onclick="print()">Imprimir / reimprimir</button> <a class="btn" href="facturas.php">Regresar</a></div><h1>Farmacia · Factura</h1><p><b>Número:</b> <?=htmlspecialchars($venta['numero'])?> &nbsp; <b>Fecha:</b> <?=htmlspecialchars($venta['fecha'])?></p><p><b>Cliente:</b> <?=htmlspecialchars($venta['cliente'])?> &nbsp; <b>ID:</b> <?=htmlspecialchars($venta['id_cliente']??'')?></p><p><b>Pago:</b> <?=htmlspecialchars($venta['metodo_pago'])?> &nbsp; <b>Estado:</b> <?=htmlspecialchars($venta['estado'])?></p><table><thead><tr><th>Medicamento</th><th>Precio</th><th>Cantidad</th><th>Subtotal</th></tr></thead><tbody><?php while($p=$items->fetch_assoc()){ ?><tr><td><?=htmlspecialchars($p['nombre_producto'])?></td><td>RD$ <?=number_format((float)$p['precio'],2)?></td><td><?=(int)$p['cantidad']?></td><td>RD$ <?=number_format((float)$p['subtotal'],2)?></td></tr><?php } ?></tbody></table><p class="right">Descuento: RD$ <?=number_format((float)$venta['descuento'],2)?></p><p class="right">Impuesto: RD$ <?=number_format((float)$venta['impuesto'],2)?></p><h2 class="right">Total: RD$ <?=number_format((float)$venta['total'],2)?></h2><?php if($venta['estado']==='completada'){ ?><form class="noprint" method="post" action="anular_venta.php" onsubmit="return confirm('¿Anular esta factura y devolver las unidades al inventario?')"><input type="hidden" name="id" value="<?=(int)$id?>"><label>Motivo de anulación <input name="motivo" maxlength="255" required></label><button class="btn">Anular venta</button></form><?php } ?></main></body></html>
